146	// checkpointSubtreePath joins a checkpoint-relative git tree path from a base and
147	// trailing segments using path.Join. Git tree paths are always "/"-separated, so
148	// this uses the stdlib path package (never path/filepath, which would emit "\" on
149	// Windows and corrupt tree keys). path.Join cleans separators, so base may be ""
150	// (per-checkpoint-ref root), a clean dir ("a3/b2.../0"), or a trailing-slash dir
151	// ("a3/b2.../"): checkpointSubtreePath("", "0", "metadata.json") == "0/metadata.json"
152	// and checkpointSubtreePath("a3/b2.../", "0", "metadata.json") == "a3/b2.../0/metadata.json".
153	// Callers therefore need not maintain the trailing-slash invariant by hand.
154	func checkpointSubtreePath(base string, segs ...string) string {
155		if len(segs) == 0 {
156			// path.Join with no segments would clean a "" base to "." — an invalid
157			// git tree key. At the ref root the correct key is ""; for a non-empty
158			// base, clean it to keep the trailing-slash-stripping behavior.
159			if base == "" {
160				return ""
161			}
162			return path.Clean(base)
163		}
164		return path.Join(append([]string{base}, segs...)...)
165	}
